__NUXT_JSONP__("/careers", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{details:{slug:"en",pageTitle:"Make your mark at MLI. | Mentor Language Institute",pageDescription:"We’re always on the lookout for enthusiastic, qualified ESL and Test Preparation instructors to add to our team.",header:"Make your mark at MLI.",image:"\u002Fimages\u002Fwhat-is-mli\u002Fcareer\u002Fstaff.PNG",subtitle:["Exciting Career Opportunities at MLI - Join Our Team Today!","\u003Cb\u003EAre you a passionate and qualified ESL, Conversation English, or TOEFL instructor looking to make a positive impact on students' lives? Look no further than MLI!\u003C\u002Fb\u003E \u003Cbr \u002F\u003EWe are dedicated to education and empowering our students to achieve their academic, work, and personal goals. Our instructors create a motivating and engaging classroom environment that inspires students to be their best selves.","At MLI, we value our instructors and offer a supportive work environment with paid monthly meetings\u002Fworkshops, an easy-to-follow curriculum, and dedicated Program Coordinator support. Plus, our Westwood and Hollywood campuses offer flexible morning, afternoon, and evening shifts to fit your schedule.","\u003Cb\u003ETeacher Benefits:\u003C\u002Fb\u003E \u003Cbr \u002F\u003E As an MLI instructor, you'll enjoy a $100 monthly healthcare contribution for full-time instructors after 30 days, paid parking, 4-day work week with Monday to Thursday shifts, paid monthly teacher's meetings, and up to one week of paid vacation after one year of service. ","\u003Cb\u003ETeacher Qualifications:\u003C\u002Fb\u003E \u003Cbr \u002F\u003E To qualify for our instructor positions, you'll need a minimum of a bachelor's degree and one year of ESL and\u002For test preparation teaching experience, be a native English speaker (USA preferred), and have basic computer skills (Google Docs, Google Sheets, Email, Zoom). We can only consider local, qualified candidates, and interviews are conducted exclusively in Southern California. Must be a US citizen or have permission to work in the US.","\u003Cb\u003EHow to Apply:\u003C\u002Fb\u003E \u003Cbr \u002F\u003EDon't miss your chance to join our team and help us make a positive impact on the world. Fill out the form below and upload your resume and brief cover letter. Let us know your preferred campus, schedule availability, and preferred position with our company. While we appreciate all applicants' interest, only qualified candidates will be contacted for interviews.","We sincerely LOVE education and strive to make a positive difference in the lives of our students. Our instructors and staff create environments that truly motivate students to be their best. MLI’s students receive a rewarding experience during their studies, which propels them to succeed in their future academic, work and personal goals."],form:[{type:d,name:"fname",label:"First Name",isRequired:a},{type:d,name:"lname",label:"Last Name",isRequired:a},{type:e,name:e,label:"Your Email",isRequired:a},{type:d,name:"phone",label:"Phone Number",isRequired:a},{type:f,description:"Desired Position (check multiple if applicable)",isRequired:a},{type:b,name:g,label:g,group:c},{type:b,name:h,label:h,group:c},{type:b,name:i,label:i,group:c},{type:b,name:j,label:j,group:c},{type:b,name:k,label:k,group:c},{type:b,name:l,label:l,group:c},{type:f,description:"Campus Preference",isRequired:a},{type:b,name:m,label:m,group:n},{type:b,name:o,label:o,group:n},{upload:a,upload_details:{key:"resume",description:"Upload Resume Click Here",style:p},isRequired:a},{upload:a,upload_details:{key:"coverLetter",description:"Upload Cover Letter Click Here",style:p},isRequired:a},{type:"textarea",name:"message",label:"Availability Schedule",isRequired:a}],btn_label:"Send",dir:"\u002Fcareers",path:"\u002Fcareers\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:28.702Z",updatedAt:"2025-05-26T12:06:27.706Z"},lang:q,$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:a,forcedJSONParsing:a,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:q,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}}}],fetch:{},mutations:q}}(true,"groupOfCheckboxes","positions","text","email","note2","ESL Class Teacher","Conversation Class Teacher","TOEFL \u002F Test Prep Class Teacher","Student Advisor","Administrative Assistance","Marketing \u002F Sales representative","Westwood","campus","Hollywood","style_1",void 0)));